144	+/**
145	+ * Install php-fpm on a Debian/Ubuntu (apt) target and return its real fpm socket,
146	+ * so a migrated PHP doc-root (WordPress/Laravel/plain PHP) is actually executed
147	+ * instead of collapsing to `try_files … =404` — the silent failure that hit every
148	+ * PHP site whenever the target did not already happen to run php-fpm. (FIX WEB-1)
149	+ *
150	+ * `major` is the SOURCE's PHP major ("8.1") when we could discover it. It is
151	+ * strictly validated (`\d` or `\d.\d`) before it ever reaches a shell, and it is
152	+ * only an OPTIMISTIC first attempt: a specific major is frequently absent from the
153	+ * target distro's default apt repo (Ubuntu 24.04 ships 8.3, not 8.1, without a
154	+ * PPA), so we always fall back to the unversioned `php-fpm` metapackage, which
155	+ * resolves to whatever current stable the distro provides. The resulting socket
156	+ * is read back from disk (`/run/php/php*-fpm.sock`) rather than assumed, so it is
157	+ * correct regardless of which major actually installed.
158	+ *
159	+ * Non-apt targets, or an install that produces no socket, return ok:false so the
160	+ * caller can HONESTLY refuse — name the missing `php<major>-fpm` — never serve the
161	+ * site as a silent 404.
162	+ */
163	+async function ensurePhpFpm(
164	+  conn: Client,
165	+  major: string,
166	+  say?: (line: string) => Promise<void>
167	+): Promise<{ ok: boolean; socket: string; label: string; reason?: string }> {
168	+  const beat = <T,>(what: string, run: () => Promise<T>): Promise<T> => (say ? withHeartbeat(what, say, run) : run());
169	+  const validMajor = /^\d(?:\.\d)?$/.test(major) ? major : "";
170	+  const label = validMajor ? `php${validMajor}-fpm` : "php-fpm";
171	+
172	+  // php-fpm is only installed here on apt targets, matching the existing runtime
173	+  // install path; anything else is refused rather than guessed.
174	+  const isApt = await shOk(conn, `command -v apt-get >/dev/null 2>&1`);
175	+  if (!isApt) return { ok: false, socket: "", label, reason: "non-apt" };
176	+
177	+  const APT_ENV = "DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a NEEDRESTART_SUSPEND=1";
178	+  const APT_OPTS = `-o Dpkg::Options::="--force-confdef" -o Dpkg::Options::="--force-confold"`;
179	+  await beat("finishing any half-configured package install", () =>
180	+    execRemote(conn, `${APT_ENV} dpkg --configure -a >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => ({ code: 0, stdout: "", stderr: "" }))
181	+  );
182	+  await beat("refreshing the package index (apt-get update)", () =>
183	+    execRemote(conn, `${APT_ENV} apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => ({ code: 0, stdout: "", stderr: "" }))
184	+  );
185	+
186	+  const exts = (m: string) =>
187	+    `php${m}-fpm php${m}-mysql php${m}-cli php${m}-curl php${m}-gd php${m}-mbstring php${m}-xml php${m}-zip`;
188	+  // Prefer the source's major, then fall back to the distro's default metapackages.
189	+  const attempts = [...(validMajor ? [exts(validMajor)] : []), "php-fpm php-mysql php-cli php-curl php-gd php-mbstring php-xml php-zip"];
190	+
191	+  for (const pkgs of attempts) {
192	+    await beat(`installing PHP (${pkgs.split(" ")[0]})`, () =>
193	+      execRemote(conn, `${APT_ENV} apt-get install -y ${APT_OPTS} ${pkgs}`, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }))
194	+    );
195	+    // Enable + start whichever versioned fpm unit the install produced, then read
196	+    // the socket back off disk — never assume the major that actually landed.
197	+    const sock = clean(
198	+      (
199	+        await sh(
200	+          conn,
201	+          `svc=$(systemctl list-unit-files --type=service 2>/dev/null | awk '/^php[0-9.]*-fpm\\.service/{print $1; exit}'); ` +
202	+            `[ -n "$svc" ] && systemctl enable --now "$svc" >/dev/null 2>&1; ` +
203	+            `ls -1 /run/php/php*-fpm.sock /var/run/php/php*-fpm.sock 2>/dev/null | head -n1`,
204	+          SETUP_TIMEOUT_MS
205	+        )
206	+      ).stdout,
207	+      255
208	+    );
209	+    if (validPath(sock)) return { ok: true, socket: sock, label: pkgs.split(" ")[0] };
210	+  }
211	+  return { ok: false, socket: "", label, reason: "install-failed" };
212	+}
